    --error-color: #dc2626;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    line-height: 1.5;
    color: var(--text-main);
    background-color: var(--background-color);
}

/* Accessibility */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: white;
    padding: 8px 16px;
    z-index: 100;
    font-weight: bold;
    text-decoration: none;
    transition: top 0.2s;
}

.skip-link:focus {
    top: 0;
}

:focus-visible {
    outline: 3px solid var(--focus-ring);
    outline-offset: 2px;
}

/* Header */
.site-header {
    background: var(--surface-color);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    z-index: 10;
}

.header-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 1rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--primary-color);
    text-decoration: none;
}

.main-nav ul {
    list-style: none;
    display: flex;
    gap: 1.5rem;
}

.main-nav a {
    color: var(--secondary-color);
    text-decoration: none;
    font-weight: 600;
}

.main-nav a:hover, .main-nav a:focus {
    color: var(--accent-color);
    text-decoration: underline;
}

.header-actions {
    display: flex;
    gap: 1rem;
}

.icon-btn {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    color: var(--secondary-color);
    padding: 0.5rem;
    display: flex;
    align-items: center;
    justify-content: center;
}

.icon-btn:hover {
    color: var(--accent-color);
}

/* Layout */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

#main-content {
    outline: none;
}

section {
    margin-bottom: 4rem;
}

.section-title {
    font-size: 1.8rem;
    margin-bottom: 1.5rem;
    color: var(--primary-color);
}

/* Hero */
.hero {
    background: var(--primary-color);
    color: white;
    padding: 4rem 1rem;
    text-align: center;
    border-radius: 8px;
    margin-bottom: 3rem;
}

.hero h1 {
    font-size: 2.5rem;
    margin-bottom: 1rem;
}

.hero p {
    font-size: 1.2rem;
    color: #cbd5e1;
    margin-bottom: 2rem;
    max-width: 600px;
    margin-left: auto;
    margin-right: auto;
}

.btn {
    display: inline-block;
    padding: 0.75rem 1.5rem;
    background: var(--accent-color);
    color: white;
    text-decoration: none;
    border-radius: 4px;
    font-weight: 600;
    border: none;
    cursor: pointer;
    text-align: center;
}

.btn:hover, .btn:focus {
    background: #1d4ed8;
}

/* Product Grid */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 2rem;
}

.product-card {
    background: var(--surface-color);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    overflow: hidden;
    transition: transform 0.2s, box-shadow 0.2s;
    display: flex;
    flex-direction: column;
    position: relative;
}

.product-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
}

.product-image {
    width: 100%;
    height: 250px;
    background: #e2e8f0;
    object-fit: cover;
}

.product-info {
    padding: 1.5rem;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.product-title {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.product-title a {
    color: var(--primary-color);
    text-decoration: none;
}

.product-title a::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 1;
}

.product-price {
    font-weight: 700;
    color: var(--text-main);
    margin-bottom: 1rem;
    font-size: 1.1rem;
}

.product-old-price {
    text-decoration: line-through;
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-left: 0.5rem;
}

.deal-badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background: var(--error-color);
    color: white;
    padding: 0.25rem 0.5rem;
    border-radius: 4px;
    font-size: 0.8rem;
    font-weight: 700;
    z-index: 2;
}

.add-to-cart {
    margin-top: auto;
    width: 100%;
    background: white;
    color: var(--primary-color);
    border: 2px solid var(--primary-color);
    position: relative;
    z-index: 2;
}

.add-to-cart:hover, .add-to-cart:focus {
    background: var(--primary-color);
    color: white;
}

/* Editorial */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.editorial-card {
    background: var(--surface-color);
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid var(--border-color);
    position: relative;
}

.editorial-image {
    width: 100%;
    height: 250px;
    background: #cbd5e1;
    object-fit: cover;
}

.editorial-content {
    padding: 1.5rem;
}

.editorial-date {
    font-size: 0.85rem;
    color: var(--text-muted);
    margin-bottom: 0.5rem;
    display: block;
}

.editorial-title {
    font-size: 1.2rem;
    margin-bottom: 1rem;
}

.editorial-title a {
    color: var(--primary-color);
    text-decoration: none;
}

.editorial-title a::after {
    content: '';
    position: absolute;
    inset: 0;
}

.editorial-title a:hover, .editorial-title a:focus {
    text-decoration: underline;
}

/* Footer */
.site-footer {
    background: var(--primary-color);
