}

.footer-section h3 {
    font-size: 1.2rem;
    margin-bottom: 1rem;
    color: #f1f5f9;
}

.footer-section ul {
    list-style: none;
}

.footer-section a {
    color: #cbd5e1;
    text-decoration: none;
    line-height: 2;
}

.footer-section a:hover, .footer-section a:focus {
    color: white;
    text-decoration: underline;
}

.sr-only {
    position: absolute;
