    background: var(--primary-color);
    color: white;
}

/* Editorial */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 2rem;
}

.editorial-card {
    background: var(--surface-color);
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid var(--border-color);
    position: relative;
}

.editorial-image {
    width: 100%;
    height: 250px;
    background: #cbd5e1;
    object-fit: cover;
}

.editorial-content {
    padding: 1.5rem;
}

.editorial-date {
    font-size: 0.85rem;
    color: var(--text-muted);
    margin-bottom: 0.5rem;
    display: block;
}

.editorial-title {
    font-size: 1.2rem;
    margin-bottom: 1rem;
}

.editorial-title a {
    color: var(--primary-color);
    text-decoration: none;
}

.editorial-title a::after {
    content: '';
    position: absolute;
    inset: 0;
}

.editorial-title a:hover, .editorial-title a:focus {
    text-decoration: underline;
}

/* Footer */
.site-footer {
    background: var(--primary-color);
    color: white;
    padding: 3rem 1rem;
    margin-top: 4rem;
}

.footer-container {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 2rem;
}

.footer-section h3 {
    font-size: 1.2rem;
    margin-bottom: 1rem;
    color: #f1f5f9;
}

.footer-section ul {
    list-style: none;
}

.footer-section a {
    color: #cbd5e1;
    text-decoration: none;
    line-height: 2;
}

.footer-section a:hover, .footer-section a:focus {
    color: white;
    text-decoration: underline;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    clip-path: inset(50%);
    white-space: nowrap;
    border-width: 0;
}

@media (max-width: 768px) {
    .main-nav {
        display: none;
    }
}

